export const combineInitialState = allInitialStates => {
    
  const globalState = {};

    var result;
    result = Object.keys(allInitialStates).reduce(function (r, k) {
        return r.concat(allInitialStates[k]);
    }, []);
      
  let merged = Object.assign(...allInitialStates);

  return merged;
};
